-- Added for experimental Firebird support (2026-10-18); see MODIFICATIONS.md.
-- Run only against the owned, synthetic Firebird 3 Client laboratory.
CREATE TABLE "AutoUser" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" VARCHAR(255) CHARACTER SET UTF8 NOT NULL,
  "name" VARCHAR(255) CHARACTER SET UTF8,
  "tag" VARCHAR(64) CHARACTER SET UTF8 DEFAULT 'db-default' NOT NULL,
  "active" BOOLEAN DEFAULT TRUE NOT NULL,
  "balance" DECIMAL(18, 4),
  CONSTRAINT "AutoUser_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "AutoUser_email_key" UNIQUE ("email")
);
CREATE TABLE "AutoPost" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title" VARCHAR(255) CHARACTER SET UTF8 NOT NULL,
  "authorId" INTEGER NOT NULL,
  CONSTRAINT "AutoPost_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "AutoPost_author_fkey" FOREIGN KEY ("authorId") REFERENCES "AutoUser" ("id")
);
CREATE TABLE "BigAuto" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "note" VARCHAR(255) CHARACTER SET UTF8,
  CONSTRAINT "BigAuto_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "IdentityOnly" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  CONSTRAINT "IdentityOnly_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "LegacyAuto" (
  "id" INTEGER NOT NULL,
  "note" VARCHAR(255) CHARACTER SET UTF8 NOT NULL,
  CONSTRAINT "LegacyAuto_pkey" PRIMARY KEY ("id")
);
CREATE SEQUENCE "LegacyAutoSeq";
CREATE TRIGGER "LegacyAuto_insert" FOR "LegacyAuto" ACTIVE BEFORE INSERT POSITION 0 AS
BEGIN
  IF (NEW."id" IS NULL) THEN NEW."id" = NEXT VALUE FOR "LegacyAutoSeq";
END;
